#!/usr/bin/env python3
"""Regenerate the CSX-061_Q2 rainfall threshold-concentration ground truth."""

from __future__ import annotations

import datetime as dt
import json
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-061_Q2"
EVENT_ID = "CSX-061"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

MM_PER_INCH = 25.4
RECORD_HOUR_THRESHOLD_MM = 75.0
REGIONAL_TOTAL_THRESHOLD_MM = 250.0
HIGH_HOUR_SHARE_THRESHOLD_PERCENT = 30.0


def load_json(rel_path: str) -> Any:
    with (PACKAGE_DIR / rel_path).open("r", encoding="utf-8-sig") as f:
        return json.load(f)


def read_text(rel_path: str) -> str:
    return (PACKAGE_DIR / rel_path).read_text(encoding="utf-8", errors="ignore")


def clean_html(text: str) -> str:
    text = re.sub(r"<script[\s\S]*?</script>", " ", text, flags=re.I)
    text = re.sub(r"<style[\s\S]*?</style>", " ", text, flags=re.I)
    text = re.sub(r"<[^>]+>", " ", text)
    text = text.replace("&nbsp;", " ").replace("&amp;", "&").replace("&#039;", "'")
    return re.sub(r"\s+", " ", text).strip()


def nested(d: dict[str, Any], *keys: str, default: Any = None) -> Any:
    cur: Any = d
    for key in keys:
        if not isinstance(cur, dict) or key not in cur:
            return default
        cur = cur[key]
    return cur


def duration_days(start: str, end: str) -> int:
    return (dt.date.fromisoformat(end) - dt.date.fromisoformat(start)).days + 1


def rounded(value: float, digits: int) -> float:
    return round(float(value), digits)


def extract_report_inches(report_text: str) -> tuple[float, float]:
    cleaned = clean_html(report_text)
    hour_match = re.search(r"wettest hour on record\s*--\s*([0-9.]+)\"", cleaned, re.I)
    total_match = re.search(r"peaked\s+just\s+above\s+([0-9.]+)\"", cleaned, re.I)
    if not hour_match or not total_match:
        raise ValueError("Required report rainfall anchors were not found")
    return float(hour_match.group(1)), float(total_match.group(1))


def build_result() -> dict[str, Any]:
    event = load_json("metadata/event.json")
    anchor = load_json(
        "data/event_reports/"
        "event_reports_003_Locked_event_anchor_September_2021_Hurricane_Ida_rainfall_flooding_in_New_York_City.json"
    )
    report = read_text("data/event_reports/event_reports_001_Locked_package_evidence_report.html")

    record_hour_in, regional_total_in = extract_report_inches(report)
    record_hour_mm = record_hour_in * MM_PER_INCH
    regional_total_mm = regional_total_in * MM_PER_INCH
    record_hour_margin_mm = record_hour_mm - RECORD_HOUR_THRESHOLD_MM
    regional_total_margin_mm = regional_total_mm - REGIONAL_TOTAL_THRESHOLD_MM
    record_hour_ratio = record_hour_mm / RECORD_HOUR_THRESHOLD_MM
    regional_total_ratio = regional_total_mm / REGIONAL_TOTAL_THRESHOLD_MM
    hour_share_percent = record_hour_mm / regional_total_mm * 100.0

    record_hour_pass = record_hour_mm >= RECORD_HOUR_THRESHOLD_MM
    regional_total_pass = regional_total_mm >= REGIONAL_TOTAL_THRESHOLD_MM
    concentration_class = (
        "high_hour_share"
        if hour_share_percent >= HIGH_HOUR_SHARE_THRESHOLD_PERCENT
        else "lower_hour_share"
    )
    if record_hour_pass and regional_total_pass and concentration_class == "high_hour_share":
        final_label = "dual_threshold_high_concentration_rainfall"
    elif record_hour_pass and regional_total_pass:
        final_label = "dual_threshold_lower_concentration_rainfall"
    elif record_hour_pass:
        final_label = "record_hour_threshold_only"
    elif regional_total_pass:
        final_label = "regional_total_threshold_only"
    else:
        final_label = "rainfall_thresholds_not_met"

    start = nested(anchor, "temporal_window", "start_date")
    end = nested(anchor, "temporal_window", "end_date")

    expected_values = {
        "record_hour_mm": rounded(record_hour_mm, 3),
        "regional_total_mm": rounded(regional_total_mm, 1),
        "record_hour_share_percent": rounded(hour_share_percent, 1),
        "record_hour_pass": record_hour_pass,
        "regional_total_pass": regional_total_pass,
        "concentration_classification": concentration_class,
    }
    interpretation = (
        "Ida's New York City calibration is supported by both a record-hour extreme and a storm-total lower-bound extreme, with the record hour alone equal to about one third of the regional reference."
    )

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": "rainfall_threshold_concentration_diagnostic",
        "primary_gt": {
            "record_hour": {
                "value_mm": rounded(record_hour_mm, 3),
                "threshold_mm": RECORD_HOUR_THRESHOLD_MM,
                "margin_mm": rounded(record_hour_margin_mm, 3),
                "ratio_to_threshold": rounded(record_hour_ratio, 3),
                "passes": record_hour_pass,
            },
            "regional_total": {
                "value_mm": rounded(regional_total_mm, 1),
                "threshold_mm": REGIONAL_TOTAL_THRESHOLD_MM,
                "margin_mm": rounded(regional_total_margin_mm, 1),
                "ratio_to_threshold": rounded(regional_total_ratio, 3),
                "passes": regional_total_pass,
            },
            "concentration": {
                "record_hour_share_percent": rounded(hour_share_percent, 1),
                "classification": concentration_class,
            },
            "final_label": final_label,
            "interpretation": interpretation,
        },
        "key_values": {
            "inputs": {
                "central_park_record_hour_inches": record_hour_in,
                "regional_total_reference_inches": regional_total_in,
                "regional_total_reference_note": "The report phrase 'just above 10 inches' is scored as a conservative 10.0-inch lower-bound reference.",
                "mm_per_inch": MM_PER_INCH,
            },
            "thresholds": {
                "record_hour_mm": RECORD_HOUR_THRESHOLD_MM,
                "regional_total_mm": REGIONAL_TOTAL_THRESHOLD_MM,
                "high_hour_share_percent": HIGH_HOUR_SHARE_THRESHOLD_PERCENT,
            },
            "computed": {
                **expected_values,
                "record_hour_margin_mm": rounded(record_hour_margin_mm, 3),
                "record_hour_ratio": rounded(record_hour_ratio, 3),
                "regional_total_margin_mm": rounded(regional_total_margin_mm, 1),
                "regional_total_ratio": rounded(regional_total_ratio, 3),
                "final_label": final_label,
            },
            "decision_rule": (
                "The final label is dual_threshold_high_concentration_rainfall when both rainfall "
                "thresholds pass and the record-hour share is at least 30%."
            ),
        },
        "event": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": f"{start} to {end}",
            "duration_days_inclusive": duration_days(start, end),
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "Final label and pass states",
                    "points": 3,
                    "description": (
                        "Returns dual_threshold_high_concentration_rainfall, marks both rainfall tests true, "
                        "and uses high_hour_share."
                    ),
                    "partial_credit": (
                        "Award 1-2 points for the right severe-rainfall direction with one missing or "
                        "mislabeled state."
                    ),
                },
                {
                    "name": "Record-hour conversion",
                    "points": 4,
                    "description": (
                        "Computes 3.47 in * 25.4 = 88.138 mm, margin above 75 mm = 13.138 mm, "
                        "ratio 1.175, and a passing threshold state."
                    ),
                    "partial_credit": (
                        "Award 2-3 points for correct conversion with a rounding or margin error; award "
                        "1 point for using the conversion but comparing to the wrong threshold."
                    ),
                },
                {
                    "name": "Regional-total conversion",
                    "points": 3,
                    "description": (
                        "Treats the report phrase 'just above 10 inches' as a conservative 10.0-inch lower-bound reference, then computes 10.0 in * 25.4 = 254.0 mm, margin above 250 mm = 4.0 mm, ratio 1.016, and a passing threshold state."
                    ),
                    "partial_credit": (
                        "Award 1-2 points for a correct conversion but incomplete margin or ratio reasoning."
                    ),
                },
                {
                    "name": "Concentration calculation",
                    "points": 3,
                    "description": (
                        "Computes 88.138 / 254.0 * 100 = 34.7% and classifies it as high_hour_share "
                        "under the 30% rule."
                    ),
                    "partial_credit": (
                        "Award 1-2 points for an approximate share with an omitted or misapplied class threshold."
                    ),
                },
                {
                    "name": "Decision-rule reasoning",
                    "points": 3,
                    "description": (
                        "Connects the two passed thresholds and the high-hour-share class to the final label, "
                        "and rejects a single-axis rainfall label."
                    ),
                    "partial_credit": (
                        "Award 1-2 points for reaching the label without clearly showing all rule components."
                    ),
                },
                {
                    "name": "Computed interpretation",
                    "points": 2,
                    "description": (
                        "Gives one event-specific sentence tying the numbers to short-duration extreme rainfall "
                        "embedded in a broader high-total episode."
                    ),
                    "partial_credit": (
                        "Award 1 point for a plausible but generic interpretation that is not tied to the values."
                    ),
                },
                {
                    "name": "Concise structured output",
                    "points": 2,
                    "description": "Returns valid JSON with the requested fields and no extra planning material.",
                    "partial_credit": "Award 1 point for mostly correct fields with minor formatting issues.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
                "data/event_reports/event_reports_003_Locked_event_anchor_September_2021_Hurricane_Ida_rainfall_flooding_in_New_York_City.json",
            ],
        },
    }


def main() -> None:
    result = build_result()
    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(result, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
